	helper := ev.expansionHelper()
	val, diags := helper.evaluateForEachValue()
	ev.hclCtx = helper.forEachHCLCtx
	return val, diags
}

func (ev *forEachEvaluator) ensureKnownForImport(forEachVal cty.Value) tfdiags.Diagnostics {
	helper := ev.expansionHelper()
	helper.forEachRawValue = forEachVal
	return helper.ensureForEachKnownForImport(forEachVal)
}

