package terraform

import (
	"strings"
	"testing"

	"github.com/hashicorp/terraform/internal/addrs"
	"github.com/hashicorp/terraform/internal/configs/configschema"
	"github.com/hashicorp/terraform/internal/providers"
	"github.com/hashicorp/terraform/internal/states"
	"github.com/hashicorp/terraform/internal/tfdiags"
)

func TestTmpValidateImportBlocks(t *testing.T) {
	p := testProvider("null")
	p.GetProviderSchemaResponse = getProviderSchemaResponseFromProviderSchema(&providerSchema{
		ResourceTypes: map[string]*configschema.Block{
			"null_resource": {
				Attributes: map[string]*configschema.Attribute{},
			},
		},
	})

	m := testModule(t, "validate-import-blocks")

	ctx := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			addrs.NewDefaultProvider("null"): testProviderFuncFixed(p),
		},
	})

	diags := ctx.Validate(m, &ValidateOpts{})
	if !diags.HasErrors() {
		t.Fatalf("expected validation errors for invalid import blocks, got none")
	}

	got := diags.Err().Error()
	t.Logf("diags:\n%s", got)

	if !strings.Contains(got, "not-a-real-resource") {
		t.Errorf("expected error about missing import target config, got:\n%s", got)
	}
	if !strings.Contains(got, "some_other_undefined_thing") {
		t.Errorf("expected error about undeclared variable, got:\n%s", got)
	}
	if !strings.Contains(got, "something_not_defined") {
		t.Errorf("expected error about undeclared local, got:\n%s", got)
	}
}

func TestTmpValidateImportBlocksValid(t *testing.T) {
	p := testProvider("null")
	p.GetProviderSchemaResponse = getProviderSchemaResponseFromProviderSchema(&providerSchema{
		ResourceTypes: map[string]*configschema.Block{
			"null_resource": {
				Attributes: map[string]*configschema.Attribute{},
			},
		},
	})

	m := testModule(t, "validate-import-blocks-valid")

	ctx := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			addrs.NewDefaultProvider("null"): testProviderFuncFixed(p),
		},
	})

	diags := ctx.Validate(m, &ValidateOpts{})
	if diags.HasErrors() {
		t.Fatalf("unexpected errors: %s", diags.Err())
	}

	// also make sure plan still works
	_, diags = ctx.Plan(m, states.NewState(), DefaultPlanOpts)
	diags = tfdiags.Diagnostics(diags)
	if diags.HasErrors() {
		t.Fatalf("unexpected plan errors: %s", diags.Err())
	}
}

