	}

	got, want := diags.Err().Error(), "Invalid import id argument: The import ID cannot reference the resource being imported."
	if cmp.Diff(want, got) != "" {
		t.Fatalf("unexpected error\n%s", cmp.Diff(want, got))
	}
}

